def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False
    shifts = [k // 26] * 26
    for i in range(k % 26):
        shifts[i] += 1
    for i in range(len(s)):
        diff = (ord(t[i]) - ord(s[i])) % 26
        if diff > 0 and shifts[diff - 1] == 0:
            return False
        if diff > 0:
            shifts[diff - 1] -= 1
    return True
